/**
 * M6/M8/issue-13 Workflow: pending-queue drain over Node-RED's OWN resolved
 * routing decisions.
 *
 * Deterministic by construction: the only I/O is the awaited `executeNode`
 * Activity call (via `proxyActivities`); no Date.now()/Math.random()/fs/etc.
 * anywhere in this file. `resolveDestinations` and `runFlow` are plain,
 * side-effect free functions so they can be unit-tested directly (see A2
 * answer #2 in the M6 handoff for the grep proving this).
 *
 * Fan-out scope decision (issue #5): the M6 single-path walk followed only
 * the first destination of the first send. This has been replaced by a
 * pending-queue drain that follows EVERY destination on EVERY port of EVERY
 * send emitted by a node, so a true branch (A -> B and A -> C) executes both
 * branches. `resolveNext` (singular) was replaced by `resolveDestinations`
 * (plural, returns an array) rather than kept alongside it - the old
 * single-id return value has no remaining caller once the loop walks a
 * queue instead of a single `node`/`msg` pair, so keeping both would just be
 * dead/duplicate routing logic.
 *
 * Resolved routing (issue #13): each Activity result's `sends` entries now
 * carry the `destinationId` Node-RED itself already resolved (via Capture's
 * `preRoute` hook, one entry per actual wired destination - capture.js).
 * The loop enqueues each captured `destinationId` DIRECTLY, with no per-port
 * dedupe and no re-resolution from `graph`: two distinct `node.send()` calls
 * on the same port are two distinct captured entries and remain two
 * distinct downstream deliveries, and any Node-RED routing richer than a
 * flat `wires[port]` lookup (Link nodes, subflows, etc.) is honored for
 * free, since Node-RED - not this file - decided the destination.
 * `resolveDestinations`/`graph` remain only as a fallback for callers that
 * supply `{port, msg}` without a `destinationId` (kept for backward
 * compatibility during the transition - see its call site below).
 *
 * Execution is drained wave-by-wave (issue #24): every item currently
 * pending is dispatched CONCURRENTLY via `Promise.all` (a "wave"), and only
 * once the entire wave has settled are that wave's `sends` collected into
 * the NEXT wave. This is still deterministic Workflow code - `Promise.all`
 * over already-scheduled Activity calls, no real OS threads, no
 * `Date.now()`/`Math.random()`/fs access - it just stops forcing
 * independent branches (e.g. two fan-out branches that both feed the same
 * downstream Join node) to await one another one at a time. This is what
 * makes a Join/fan-in node's second required input actually get scheduled
 * instead of deadlocking behind the first branch's still-pending Activity
 * call (see issue #24). Fan-in is still never merged/deduplicated (the
 * shared node is invoked once per incoming branch, same as before); a loop
 * in `graph` would still drain forever, so loops remain out of scope and
 * are not guarded against here.
 */

"use strict";

const { proxyActivities, ApplicationFailure, sleep, condition, defineSignal, setHandler } = require("@temporalio/workflow");
const { validateSuspension } = require("./suspension");

// issue #89: ONE generic Workflow signal for every durable "wait for an
// external event" suspension, regardless of node type (per the issue's
// "generic Temporal signal shape" requirement - no per-node-type signal
// definitions). Payload is always `{key, data}`; `data` must already be
// plain/serializable (normal Temporal payload-converter rules apply, no
// second serializer is added here).
const resumeSignal = defineSignal("nodeRedTemporalResume");

// Non-retryable node/business errors (M5 `activities.js` codes). These are
// never worth retrying: a bad wire graph, a stale flow deploy, or a node's
// own thrown error will fail identically on every retry attempt.
const NON_RETRYABLE_CODES = new Set([
    "FLOW_VERSION_MISMATCH",
    "NODE_NOT_FOUND",
    "NODE_ERROR",
    "NODE_TIMEOUT",
    "FLOW_EXECUTION_LIMIT",
    // issue #89: a suspension descriptor an adapter produced is malformed,
    // or a resume input arrived with no compatible adapter installed. Both
    // are deterministic contract violations - retrying changes nothing.
    "SUSPENSION_INVALID",
    "SUSPENSION_UNSUPPORTED"
]);

// issue #34: deterministic safety rail against an accidental/non-terminating
// cyclic flow growing Workflow history (and Activity cost) without bound.
// This is NOT a cycle-detection subsystem - it is a single plain counter of
// total node Activity invocations across the whole run, checked before each
// wave is dispatched. A legitimate finite loop that stays under this count
// is completely unaffected; a runaway loop fails fast and clearly instead of
// growing forever. `1000` is a conservative default for an early alpha -
// callers may override it per-run via `input.maxNodeExecutions` (still a
// plain, deterministic Workflow input value - no env/config is ever read
// from Workflow code).
const DEFAULT_MAX_NODE_EXECUTIONS = 1000;

/**
 * Given the wire graph and a single send emitted by `nodeId`, resolve ALL
 * destination node ids wired to the port the message was sent on. Returns
 * an empty array when there is nothing further to route to (end of path on
 * that port, unwired port, or `send` itself is undefined/null).
 *
 * @param {Object<string, Array<Array<string>>>} graph
 * @param {string} nodeId - the node that produced `send`
 * @param {{port:number, msg:object}} [send]
 * @returns {string[]}
 */
function resolveDestinations(graph, nodeId, send) {
    if (!send) {
        return [];
    }
    const wires = graph && graph[nodeId];
    const port = wires && wires[send.port];
    return port || [];
}

/**
 * Pure routing loop, parameterized over `executeNode` so it can be unit
 * tested with a mock Activity function - the actual Temporal Workflow entry
 * point (`executeFlow` below) supplies the real, Temporal-proxied Activity.
 *
 * Walks a breadth-first wave-queue of `{nodeId, msg}` work items instead of
 * a single `node`/`msg` pair (issue #5): every send emitted by a node fans
 * out to every destination on the port it sent on, and each destination is
 * pushed onto the next wave. Each wave's items are dispatched CONCURRENTLY
 * via `Promise.all` (issue #24) - the wave only advances once every item in
 * it has settled - so ordering stays deterministic (still breadth-first
 * over the fan-out tree) while independent branches within the same wave no
 * longer block one another. This is what unblocks a Join/fan-in node: both
 * of its incoming branches land in the same wave and are dispatched
 * together, so the Join's second required message is actually scheduled
 * instead of waiting behind the first branch's still-pending Activity call.
 *
 * Node-RED's own `preRoute` hook already fires once PER WIRED DESTINATION,
 * not once per `node.send()` call (`Flow.js` `handleOnSend`/`handlePreRoute`:
 * "preRoute - called once for each SendEvent object in turn"). Capture (M2)
 * records one `{port, destinationId, msg}` entry per destination, so
 * `result.sends` already contains N entries for a port with N wired
 * destinations - it is not one logical send that this loop must additionally
 * fan out via the graph. Since each entry already carries Node-RED's own
 * resolved `destinationId` (issue #13), this loop enqueues each entry's
 * `destinationId` directly - no dedupe by port, no re-resolution from
 * `graph` - so each wired destination is invoked exactly once, and two
 * distinct `send()` calls on the same port produce two distinct downstream
 * deliveries instead of being collapsed.
 *
 * Any Activity result carrying `error` ends the run immediately by throwing
 * an `ApplicationFailure` marked `nonRetryable: true` (approach (a) from the
 * M6 plan - see handoff for the rejected alternative and why). This still
 * aborts the ENTIRE run, including any other branches still queued in later
 * waves: a fan-out flow with an error in one branch does not continue
 * draining sibling waves, matching the M6 fail-loud behavior for the linear
 * case. Other items already dispatched in the SAME wave as the failing one
 * have already been sent to their Activity (they were dispatched together
 * via `Promise.all`), but their `sends` are simply never collected into a
 * next wave once the error is found - the error still wins.
 *
 * M4 source fan-out: `input.initial` (an array of `{nodeId, msg}` items,
 * one per source-ingress destination - see worker.js) seeds the SAME pending
 * queue as today's single `startNode`/`startMsg` pair, so a single Inject
 * fanning out to two downstream nodes runs both branches within ONE
 * Workflow Execution. When `initial` is provided it takes precedence over
 * `startNode`/`startMsg` (mutually exclusive start mechanisms - the
 * multi-wire in-graph fan-out exercised by the existing `startNode` tests
 * above is unaffected, since it is driven by `graph`, not by how many
 * items seed `pending`).
 *
 * issue #58 M1: an optional `resultNodeId` designates a specific node as the
 * flow's explicit result marker. When absent, behavior/return shape is
 * exactly unchanged. When present, every wave is pre-scanned (before
 * dispatch) for how many of its items target `resultNodeId`: a 2nd+ delivery
 * anywhere in the run throws a nonRetryable `FLOW_RESULT_AMBIGUOUS`
 * `ApplicationFailure` BEFORE that wave is even dispatched (deterministic
 * regardless of Activity settle order); exactly one delivery records that
 * item's own `msg` (the msg handed to `executeNode`, not a transformed
 * output) as `resultMsg` on the final return value; zero deliveries by the
 * time the queue drains throws a nonRetryable `FLOW_RESULT_MISSING`. The
 * marker node still executes normally (still gets its own `executeNode`
 * call, can still `send()` further) - this only captures `msg`, it does not
 * terminate routing.
 *
 * issue #75: an optional `httpBridge` flag marks a run as started from the
 * stock HTTP In transport bridge (`worker.js`'s `createOnHttpBridgeIngress`).
 * When set, EVERY `executeNode` Activity call carries `httpBridge: true` so
 * `activities.js` can decide, per-node, whether to inject its response
 * recorder (only for the real stock "http response" node type - see
 * activities.js/httpNodeBridge.js) - and this loop aggregates whichever
 * Activity results carried back an `httpResponse` descriptor: zero by the
 * time the queue drains -> nonRetryable `HTTP_RESPONSE_MISSING`; exactly
 * one -> recorded as `output.httpResponse`; two or more -> nonRetryable
 * `HTTP_RESPONSE_AMBIGUOUS`. No static "which node is the responder" is
 * required - whichever stock HTTP Response node actually executes wins.
 * Aggregation is done in `wave` (dispatch) order, not settle order, so it
 * stays deterministic on replay regardless of which Activity call happens
 * to resolve first within a wave.
 *
 * issue #82: an optional `httpBridgeId` (present iff `httpBridge` is true)
 * is the SAME plain, serializable ingress-generated identifier `worker.js`
 * derives its Workflow ID from. It is threaded verbatim into every
 * HTTP-bridge `executeNode` Activity input alongside `httpBridge: true` so
 * `worker.js`'s process-local early-response registry (keyed by this same
 * id) can be notified by whichever Activity actually executes the stock
 * HTTP Response node - see `activities.js`'s `onHttpResponse` DI hook and
 * `worker.js`'s `createOnHttpBridgeIngress`/bridge registry docblocks for
 * the full mechanism. This is a plain opaque string as far as this file is
 * concerned - no Activity Context/Workflow-ID rediscovery is ever needed
 * here, keeping this Workflow deterministic and framework-agnostic on the
 * Activity side.
 *
 * @param {{executeNode:function, graph:object, flowVersion:string, startNode:string, startMsg:*, initial:Array<{nodeId:string, msg:*}>, resultNodeId?:string, httpBridge?:boolean, httpBridgeId?:string}} input
 * @returns {Promise<{flowVersion:string, lastNode:(string|undefined), resultMsg?:*, httpResponse?:object}>}
 */
async function runFlow({ executeNode, createExecuteNode, graph, nodeMeta, flowVersion, startNode, startMsg, initial, activityTaskQueue, maxNodeExecutions, nodeExecutionTimeoutMs, resultNodeId, httpBridge, httpBridgeId, sleepFn, conditionFn, signalInbox }) {
    let wave = initial ? initial.slice() : (startNode ? [{ nodeId: startNode, msg: startMsg }] : []);
    const invocationCounts = new Map();
    const maxExecutions = maxNodeExecutions || DEFAULT_MAX_NODE_EXECUTIONS;
    let totalExecutions = 0;
    let lastNode;
    // issue #58 M1: generic explicit Workflow result marker. Deliveries are
    // counted deterministically BEFORE dispatching the wave they occur in
    // (pre-scan), so an ambiguous (2nd+) delivery is rejected before any
    // Activity in that wave is even called - it must not depend on which
    // Activity call happens to settle first.
    let resultDeliveryCount = 0;
    let resultMsg;
    // issue #75: collected in wave/dispatch order (deterministic), not
    // settle order - see docblock above.
    let httpResponses = [];
    // issue #89: detached suspend+resume chains currently in flight. Each
    // entry is a Promise<{current, result}> - identical shape to a normal
    // settled wave item - that resolves only once its durable wait (timer
    // sleep or signal condition) completes AND the resume Activity call has
    // itself settled. Kept OUTSIDE `wave` deliberately: a suspended branch
    // must never block unrelated ready work in `wave`/`nextWave` from
    // draining (issue #89's scheduling requirement) - the outer loop keeps
    // examining `wave` first and only falls back to racing this array once
    // there is no other ready work left.
    const pendingSuspensions = [];

    /**
     * Turns one settled Activity result (ordinary OR a resumed suspension's
     * final result - both are the exact same `{sends, error?, httpResponse?}`
     * shape) into the next wave's items, throwing a nonRetryable
     * ApplicationFailure on a node error exactly as before. Shared by both
     * the main per-wave dispatch loop and the suspension-resume path so
     * there is exactly one place that understands "what does a settled
     * result mean for routing" (issue #13's resolved-routing invariant
     * applies identically to both).
     */
    function settleOne(current, result) {
        if (result.error) {
            throw ApplicationFailure.create({
                message: `node ${current.nodeId} failed: [${result.error.code}] ${result.error.message}`,
                type: result.error.code,
                nonRetryable: NON_RETRYABLE_CODES.has(result.error.code),
                details: [result.error]
            });
        }
        lastNode = current.nodeId;
        if (httpBridge && result.httpResponse) {
            httpResponses.push(result.httpResponse);
        }
        const items = [];
        const sends = result.sends || [];
        for (const send of sends) {
            // issue #13: Node-RED has already resolved exactly which
            // destination this send routed to (Capture's `preRoute` hook
            // fires once per actual wired destination - see capture.js).
            // Enqueue that resolved destination directly: no per-port
            // dedupe (two distinct `node.send()` calls on the same port
            // are two distinct captured entries and must stay two distinct
            // downstream deliveries) and no re-resolution from `graph`
            // (which would just rebuild routing Node-RED already did).
            if (send.destinationId) {
                items.push({ nodeId: send.destinationId, msg: send.msg });
                continue;
            }
            // Fallback for callers that only supply {port, msg} (e.g. unit
            // tests exercising `resolveDestinations` directly, or any
            // pre-issue-13 caller not yet updated) - resolves from the raw
            // wire graph as before. Remove once nothing depends on it.
            const destinations = resolveDestinations(graph, current.nodeId, send);
            for (const destinationId of destinations) {
                items.push({ nodeId: destinationId, msg: send.msg });
            }
        }
        return items;
    }

    /**
     * issue #89: schedules the durable wait + resume Activity call for one
     * suspended item, WITHOUT awaiting it here - the returned Promise is
     * pushed onto `pendingSuspensions` so the caller can keep draining ready
     * work. Uses `sleepFn`/`conditionFn` (real `@temporalio/workflow`
     * `sleep`/`condition` in production, injectable fakes in unit tests -
     * same DI pattern as `heartbeat.js`'s wrapper) so this stays plain,
     * testable async code with no hidden Temporal-context requirement here.
     *
     * "Signal-before-wait" (issue #89): `signalInbox` is checked FIRST,
     * synchronously, before ever calling `conditionFn` - a signal that
     * already arrived (e.g. delivered while this node's own Activity call
     * that produced the suspension was still in flight) is picked up
     * immediately instead of racing a fresh `condition()` registration.
     *
     * Logical invocation identity (issue #89): `invocation` is the SAME
     * number assigned when this item was first dispatched (this suspend +
     * its later resume together count as exactly one graph
     * visit/`totalExecutions` increment - see the dispatch loop below,
     * which never re-increments for a resume). The resume Activity's own
     * `activityId` is still distinct and deterministic via
     * `createExecuteNode(..., true)`'s `:resume` suffix.
     */
    function scheduleSuspension(current, suspension, invocation) {
        return (async function() {
            if (suspension.type === "timer") {
                await sleepFn(suspension.durationMs);
            } else if (suspension.type === "signal") {
                if (!signalInbox.has(suspension.key)) {
                    await conditionFn(function() { return signalInbox.has(suspension.key); });
                }
            }
            const resume = { type: suspension.type, continuation: suspension.continuation };
            if (suspension.type === "signal") {
                resume.signal = signalInbox.get(suspension.key);
            }
            const call = createExecuteNode ? createExecuteNode(current.nodeId, invocation, nodeMeta, activityTaskQueue, nodeExecutionTimeoutMs, true) : executeNode;
            const activityInput = { flowVersion, nodeId: current.nodeId, msg: current.msg, resume };
            if (httpBridge) {
                activityInput.httpBridge = true;
                if (httpBridgeId) {
                    activityInput.httpBridgeId = httpBridgeId;
                }
            }
            const result = await call(activityInput);
            return { current: current, result: result };
        })();
    }

    /**
     * Resolves with the first `pendingSuspensions` entry to settle (removing
     * it from the array), preserving native `Promise.race` rejection
     * propagation (a real Activity/infra failure on a resume call must still
     * fail the whole run, exactly like a main-wave Activity failure does).
     */
    function raceSuspensions() {
        return Promise.race(pendingSuspensions.map(function(p, index) {
            return p.then(function(entry) { return { index: index, entry: entry }; });
        }));
    }

    while (wave.length || pendingSuspensions.length) {
        if (wave.length === 0) {
            // issue #89: no ready work left in THIS wave, but at least one
            // branch is durably suspended - wait for the first one to
            // resume rather than ending the run early. Sibling branches
            // that were already ready were always drained first (see the
            // dispatch below, which only ever pushes non-suspended items
            // into `nextWave`), so this is only reached once genuinely
            // nothing else is runnable right now.
            const winner = await raceSuspensions();
            pendingSuspensions.splice(winner.index, 1);
            wave = settleOne(winner.entry.current, winner.entry.result);
            continue;
        }
        if (resultNodeId) {
            const deliveriesInWave = wave.filter(function(item) { return item.nodeId === resultNodeId; });
            if (deliveriesInWave.length && resultDeliveryCount + deliveriesInWave.length > 1) {
                throw ApplicationFailure.create({
                    message: `flow result node ${resultNodeId} received more than one delivery`,
                    type: "FLOW_RESULT_AMBIGUOUS",
                    nonRetryable: true
                });
            }
            if (deliveriesInWave.length === 1) {
                resultMsg = deliveriesInWave[0].msg;
            }
            resultDeliveryCount += deliveriesInWave.length;
        }
        // issue #34: check BEFORE dispatching the wave (not per-item mid-wave)
        // so the failure is deterministic on replay regardless of which
        // Activity in the wave settles first - a wave that would push the
        // total past the configured max is rejected in its entirety.
        totalExecutions += wave.length;
        if (totalExecutions > maxExecutions) {
            throw ApplicationFailure.create({
                message: `flow exceeded the maximum of ${maxExecutions} node executions (attempted ${totalExecutions})`,
                type: "FLOW_EXECUTION_LIMIT",
                nonRetryable: true
            });
        }
        // Dispatch the ENTIRE current wave concurrently (issue #24): every
        // item pending right now is independent of every other item in the
        // same wave (they were all produced by the PREVIOUS wave's sends),
        // so there is no ordering requirement between them - only between
        // waves. `Promise.all` over already-constructed Activity proxies is
        // still deterministic Workflow code (no real threads, no
        // Date.now()/Math.random()/fs access), it just stops forcing
        // independent branches to await one another one at a time - which is
        // what deadlocked a Join/fan-in node's second required input before.
        const settled = await Promise.all(wave.map(function(current) {
            // Per-node invocation counter (issue #6): distinct per node id
            // within this run, so a fixed `node:<nodeId>` activityId scheme -
            // which would collide on any repeated visit to the same node -
            // stays unique even under fan-out/loop scenarios. Computed
            // synchronously here (before any `await`), so wave items are
            // still assigned invocation numbers in a fixed, deterministic
            // order regardless of which Activity settles first.
            const invocation = (invocationCounts.get(current.nodeId) || 0) + 1;
            invocationCounts.set(current.nodeId, invocation);
            // `createExecuteNode` (real Workflow path, see executeFlow below)
            // constructs a FRESH `executeNode` Activity proxy per invocation,
            // with that invocation's own `activityId`/`summary` -
            // proxyActivities is cheap closure construction, not I/O, so
            // doing this inside the loop does not break Workflow
            // determinism. Unit tests instead inject a single, plain
            // `executeNode` mock function directly (no per-call Activity
            // options to construct), which is why both are supported.
            const call = createExecuteNode ? createExecuteNode(current.nodeId, invocation, nodeMeta, activityTaskQueue, nodeExecutionTimeoutMs) : executeNode;
            const activityInput = { flowVersion, nodeId: current.nodeId, msg: current.msg };
            if (httpBridge) {
                activityInput.httpBridge = true;
                if (httpBridgeId) {
                    activityInput.httpBridgeId = httpBridgeId;
                }
            }
            return call(activityInput).then(function(result) {
                return { current: current, result: result, invocation: invocation };
            });
        }));

        const nextWave = [];
        for (const { current, result, invocation } of settled) {
            if (result.suspension) {
                // issue #89: this Activity call did NOT invoke the node -
                // it returned a durable wait descriptor instead. Validate
                // generically (no node-type knowledge here - only the
                // descriptor SHAPE is understood), reject a suspension
                // combined with incompatible normal sends, then detach the
                // wait+resume chain so it never blocks the rest of THIS
                // wave/`nextWave` from draining (issue #89's scheduling
                // requirement).
                if (result.sends && result.sends.length) {
                    throw ApplicationFailure.create({
                        message: `node ${current.nodeId} returned a suspension combined with non-empty sends`,
                        type: "SUSPENSION_INVALID",
                        nonRetryable: true,
                        details: [result]
                    });
                }
                let suspension;
                try {
                    suspension = validateSuspension(result.suspension);
                } catch (validationErr) {
                    throw ApplicationFailure.create({
                        message: `node ${current.nodeId} returned an invalid suspension: ${validationErr.message}`,
                        type: "SUSPENSION_INVALID",
                        nonRetryable: true,
                        details: [result.suspension]
                    });
                }
                pendingSuspensions.push(scheduleSuspension(current, suspension, invocation));
                continue;
            }
            const items = settleOne(current, result);
            for (const item of items) {
                nextWave.push(item);
            }
        }
        wave = nextWave;
    }

    if (resultNodeId && resultDeliveryCount !== 1) {
        throw ApplicationFailure.create({
            message: `flow result node ${resultNodeId} was never reached`,
            type: "FLOW_RESULT_MISSING",
            nonRetryable: true
        });
    }

    if (httpBridge) {
        if (httpResponses.length === 0) {
            throw ApplicationFailure.create({
                message: "no HTTP Response node executed for this HTTP-bridge flow",
                type: "HTTP_RESPONSE_MISSING",
                nonRetryable: true
            });
        }
        if (httpResponses.length > 1) {
            throw ApplicationFailure.create({
                message: `more than one HTTP Response node executed (${httpResponses.length})`,
                type: "HTTP_RESPONSE_AMBIGUOUS",
                nonRetryable: true
            });
        }
    }

    const output = { flowVersion, lastNode };
    if (resultNodeId) {
        output.resultMsg = resultMsg;
    }
    if (httpBridge) {
        output.httpResponse = httpResponses[0];
    }
    return output;
}

// issue #47: single runner-level node execution timeout, carried
// deterministically through Workflow input (never read from env/process
// config inside Workflow code - see `executeFlow` below). Default matches
// `capture.js`'s own DEFAULT_TIMEOUT_MS default (kept in sync manually,
// since Workflow code must never `require("./capture")` for its runtime
// value - that would pull Node-RED/Capture into the deterministic sandbox).
const DEFAULT_NODE_EXECUTION_TIMEOUT_MS = 1800000; // 30 min

// issue #47: fixed safety margin ABOVE the configured node execution
// timeout. Invariant: Capture timeout (Node-RED `done()` wait, ms) <
// Activity `startToCloseTimeout` (ms), so a node exceeding the configured
// limit always surfaces as Capture's own explicit NODE_TIMEOUT result
// first, rather than racing against/losing to Temporal's SDK killing the
// Activity attempt outright (see M6 handoff A2 #4 for the ordering
// argument this replaces/generalizes).
const ACTIVITY_TIMEOUT_SAFETY_MARGIN_MS = 5000;

// issue #88: fixed project default heartbeat timeout for every executeNode
// Activity. This is a generic detection signal for a lost Activity
// worker/process - NOT a replacement for `startToCloseTimeout` (the
// explicit max node runtime, still `nodeExecutionTimeoutMs +
// ACTIVITY_TIMEOUT_SAFETY_MARGIN_MS` above) and not a per-node-configurable
// surface. The worker-side heartbeat interval (see heartbeat.js's default
// `intervalMs`, ~20s) must stay comfortably below this value so a healthy,
// still-running Activity heartbeats several times before ever risking this
// timeout.
const ACTIVITY_HEARTBEAT_TIMEOUT_MS = 60000; // 60s

// Base ActivityOptions shared by every per-node proxy below, MINUS
// `startToCloseTimeout` - that field is now derived per-run from the
// Workflow input's configured timeout (see `createExecuteNode`), not a
// fixed constant, so it stays in lockstep with whatever value Capture was
// actually given for this run.
const BASE_ACTIVITY_OPTIONS = {
    // Retry policy for transient infra failures (thrown Activity errors,
    // e.g. worker crash mid-call). Node-level business errors never throw
    // here - executeNode always resolves - so this policy only ever governs
    // real infra retries, not node.error()/timeout retries (see A2 #1).
    retry: { maximumAttempts: 3, initialInterval: "1s", backoffCoefficient: 2 },
    // issue #88: generic periodic heartbeat detection - see
    // ACTIVITY_HEARTBEAT_TIMEOUT_MS's docblock above.
    heartbeatTimeout: ACTIVITY_HEARTBEAT_TIMEOUT_MS
};

/**
 * Pure helper (issue #6): builds the human-readable Activity `summary` from
 * a node's `{name, type}` metadata, e.g. "http request — get httpbin", or
 * just "debug" when the node has no `name`. Returns `undefined` when there
 * is no metadata for the node at all (unknown/omitted node), so `summary`
 * is simply left off the ActivityOptions rather than showing "undefined".
 *
 * @param {{name?:string, type?:string}} [meta]
 * @returns {string|undefined}
 */
function buildActivitySummary(meta) {
    if (!meta || !meta.type) {
        return undefined;
    }
    return meta.name ? `${meta.type} — ${meta.name}` : meta.type;
}

/**
 * Issue #6 observability: constructs a FRESH `executeNode` Activity proxy
 * for one specific node invocation, carrying a human-meaningful `activityId`
 * (unique per invocation of this node within the run) and `summary` (node
 * type + optional name, e.g. "http request — get httpbin") so the Temporal
 * Web UI can distinguish Activities without opening their JSON payloads.
 * `proxyActivities` is cheap closure construction (no I/O), so calling it
 * once per queue item is safe inside deterministic Workflow code.
 *
 * issue #16: `taskQueue` (when supplied) targets the Activity onto the
 * CONFIGURED Activity Task Queue, so a decoupled Workflow Worker schedules
 * `executeNode` onto a separate Activity Worker's queue rather than
 * implicitly defaulting to the Workflow's own queue (which would only ever
 * work in combined/single-queue mode).
 *
 * issue #47: `nodeExecutionTimeoutMs` (from Workflow input, ultimately the
 * runner's single configured node execution timeout) derives this
 * invocation's `startToCloseTimeout` as `nodeExecutionTimeoutMs +
 * ACTIVITY_TIMEOUT_SAFETY_MARGIN_MS` - always strictly above whatever value
 * Capture was given for the SAME run, so Capture's own NODE_TIMEOUT always
 * has time to fire first (see the constant's doc comment above).
 *
 * @param {string} nodeId
 * @param {number} invocation - 1-based count of this node id within the run
 * @param {Object<string, {name?:string, type?:string}>} [nodeMeta]
 * @param {string} [taskQueue] - Activity Task Queue to schedule this Activity onto
 * @param {number} [nodeExecutionTimeoutMs] - see DEFAULT_NODE_EXECUTION_TIMEOUT_MS
 * @param {boolean} [isResume] - issue #89: true for the resume Activity call
 *   of a suspend+resume pair. Only affects `activityId` (suffixed
 *   `:resume`, still deterministic and distinct from the original
 *   suspending call's id) - the suspend+resume pair still counts as ONE
 *   logical invocation for `invocation`/`totalExecutions` purposes (see
 *   `runFlow`'s `scheduleSuspension`, which reuses the SAME `invocation`
 *   number rather than drawing a new one).
 * @returns {function}
 */
function createExecuteNode(nodeId, invocation, nodeMeta, taskQueue, nodeExecutionTimeoutMs, isResume) {
    const summary = buildActivitySummary(nodeMeta && nodeMeta[nodeId]);
    const timeoutMs = nodeExecutionTimeoutMs || DEFAULT_NODE_EXECUTION_TIMEOUT_MS;
    const activityOptions = Object.assign({}, BASE_ACTIVITY_OPTIONS, {
        activityId: `node:${nodeId}:${invocation}${isResume ? ":resume" : ""}`,
        summary,
        startToCloseTimeout: timeoutMs + ACTIVITY_TIMEOUT_SAFETY_MARGIN_MS
    });
    if (taskQueue) {
        activityOptions.taskQueue = taskQueue;
    }
    const { executeNode } = proxyActivities(activityOptions);
    return executeNode;
}

/**
 * Temporal Workflow entry point. Registered by `worker.js` under this
 * function's name.
 *
 * issue #89: installs the ONE generic `nodeRedTemporalResume` signal
 * handler for this Workflow Execution and hands `runFlow` a deterministic
 * in-memory inbox (`Map`, keyed by the signal payload's `key`) plus the
 * real `sleep`/`condition` primitives from `@temporalio/workflow`. Handles
 * BOTH signal-before-wait (the handler may already have populated the inbox
 * before a suspension ever checks it - see `scheduleSuspension`'s
 * synchronous check) and signal-after-wait (the handler's `inbox.set` makes
 * an already-registered `condition()` resolve). Duplicate delivery for the
 * same `key` is deterministic: `Map.set` simply overwrites the previous
 * value, i.e. last-delivered-signal-wins for that key.
 *
 * @param {{graph:object, nodeMeta:object, flowVersion:string, startNode:string, startMsg:*, initial:Array<{nodeId:string, msg:*}>, activityTaskQueue?:string, maxNodeExecutions?:number}} input
 */
async function executeFlow(input) {
    const signalInbox = new Map();
    setHandler(resumeSignal, function(payload) {
        if (payload && typeof payload.key === "string") {
            signalInbox.set(payload.key, payload.data);
        }
    });
    return runFlow({
        createExecuteNode,
        graph: input.graph,
        nodeMeta: input.nodeMeta,
        flowVersion: input.flowVersion,
        startNode: input.startNode,
        startMsg: input.startMsg,
        initial: input.initial,
        activityTaskQueue: input.activityTaskQueue,
        maxNodeExecutions: input.maxNodeExecutions,
        nodeExecutionTimeoutMs: input.nodeExecutionTimeoutMs,
        resultNodeId: input.resultNodeId,
        httpBridge: input.httpBridge,
        httpBridgeId: input.httpBridgeId,
        sleepFn: sleep,
        conditionFn: condition,
        signalInbox
    });
}

module.exports = {
    resolveDestinations,
    runFlow,
    executeFlow,
    createExecuteNode,
    buildActivitySummary,
    DEFAULT_NODE_EXECUTION_TIMEOUT_MS,
    ACTIVITY_TIMEOUT_SAFETY_MARGIN_MS
};
